public class InnerCallAnalyticsCategoryTranscriptFilterFactory(Action<Humidifier.Transcribe.CallAnalyticsCategoryTypes.TranscriptFilter> factoryAction = null) : SubResourceFactory<Humidifier.Transcribe.CallAnalyticsCategoryTypes.TranscriptFilter>
{

    internal InnerCallAnalyticsCategoryRelativeTimeRangeFactory RelativeTimeRangeFactory { get; set; }

    internal InnerCallAnalyticsCategoryAbsoluteTimeRangeFactory AbsoluteTimeRangeFactory { get; set; }

    protected override Humidifier.Transcribe.CallAnalyticsCategoryTypes.TranscriptFilter Create()
    {
        var transcriptFilterResult = CreateTranscriptFilter();
        factoryAction?.Invoke(transcriptFilterResult);

        return transcriptFilterResult;
    }

    private Humidifier.Transcribe.CallAnalyticsCategoryTypes.TranscriptFilter CreateTranscriptFilter()
    {
        var transcriptFilterResult = new Humidifier.Transcribe.CallAnalyticsCategoryTypes.TranscriptFilter();

        return transcriptFilterResult;
    }
    public override void CreateChildren(Humidifier.Transcribe.CallAnalyticsCategoryTypes.TranscriptFilter result)
    {
        base.CreateChildren(result);

        result.RelativeTimeRange ??= RelativeTimeRangeFactory?.Build();
        result.AbsoluteTimeRange ??= AbsoluteTimeRangeFactory?.Build();
    }

} // End Of Class

